import{_ as t,o as a,c as r,a3 as l}from"./chunks/framework.D1iekJsc.js";const b=JSON.parse('{"title":"Fehlerbehebung","description":"MiniTavern ↔ Ollama/LM Studio — Timeout, CORS, Firewall und typische Verbindungsfehler.","frontmatter":{"title":"Fehlerbehebung","description":"MiniTavern ↔ Ollama/LM Studio — Timeout, CORS, Firewall und typische Verbindungsfehler.","head":[["meta",{"name":"keywords","content":"Tavern,AI Tavern,MiniTavern,AI Begleiter,AI Freund,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobil,Silly Tavern Android,Silly Tavern iOS,AI Roleplay,Charakterkarte,AI Chat,mobiles AI,Offline-AI,AI Geschichte,lokales LLM,Ollama,LM Studio,Lorebook,Regex,BYOK,Handbuch,Anleitung"}],["meta",{"property":"og:title","content":"Fehlerbehebung · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern ↔ Ollama/LM Studio — Timeout, CORS, Firewall und typische Verbindungsfehler."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/de/troubleshoot"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/de/troubleshoot"}]]},"headers":[],"relativePath":"de/troubleshoot.md","filePath":"de/troubleshoot.md","lastUpdated":1787224147000}'),d={name:"de/troubleshoot.md"};function i(o,e,n,s,h,c){return a(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="fehlerbehebung" tabindex="-1">Fehlerbehebung <a class="header-anchor" href="#fehlerbehebung" aria-label="Permalink to &quot;Fehlerbehebung&quot;">​</a></h1><p>Nach Symptom suchen; sonst App <strong>Einstellungen → Hilfe &amp; Feedback → Problem-Feedback</strong> (Screenshot + Problemlogs) oder <strong>Feedback-E-Mail</strong>. Bitte angeben: OS, Tool (Ollama / LM Studio / KoboldCPP …), Base URL (IP-Endsegmente maskierbar), Originalfehler.</p><h2 id="verbindung-test" tabindex="-1">Verbindung / Test <a class="header-anchor" href="#verbindung-test" aria-label="Permalink to &quot;Verbindung / Test&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Mögliche Ursache</th><th>Fix</th></tr></thead><tbody><tr><td>Timeout</td><td>anderes Wi‑Fi, Firewall, Dienst nicht auf <code>0.0.0.0</code></td><td>gleiches Netz; Port freigeben; «Dienst / LAN»-Kapitel des Tools</td></tr><tr><td>Sofort fehlgeschlagen</td><td>falsche IP/Port, Dienst aus</td><td>am PC <code>http://IP:Port/v1/models</code>; Base URL prüfen</td></tr><tr><td>localhost scheitert</td><td>localhost auf dem Handy = Handy selbst</td><td>LAN-IP des PCs</td></tr><tr><td>401 / Key-Fehler</td><td>manche lokalen Stacks prüfen Key</td><td>nicht-leerer Platzhalter oder Auth laut Tool-Doku aus</td></tr><tr><td>404 / Modell fehlt</td><td>Name ≠ lokal</td><td><code>ollama list</code> oder <code>/v1/models</code> — <strong>volle id</strong></td></tr><tr><td>Antwort, aber Chat leer/Fehler</td><td>Kompatibilität, Timeout, Modell nicht geladen</td><td>Timeout hoch; Modell load; kleineres Modell zum Pfadtest</td></tr></tbody></table><h2 id="netz-system" tabindex="-1">Netz &amp; System <a class="header-anchor" href="#netz-system" aria-label="Permalink to &quot;Netz &amp; System&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Mögliche Ursache</th><th>Fix</th></tr></thead><tbody><tr><td>PC ok, Handy nicht</td><td>Gast-Wi‑Fi / AP-Isolation</td><td>Hauptnetz; Hotspot vom Handy, PC daran</td></tr><tr><td>Sporadisch weg</td><td>PC-Schlaf, IP-Wechsel</td><td>Schlaf aus; IP neu und Verbindung aktualisieren</td></tr><tr><td>Mit VPN seltsam</td><td>Split / virtuelle Adapter</td><td>VPN testweise aus oder LAN ausschließen</td></tr></tbody></table><h2 id="url-schreibweise" tabindex="-1">URL-Schreibweise <a class="header-anchor" href="#url-schreibweise" aria-label="Permalink to &quot;URL-Schreibweise&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Richtig</th><th>Falsch</th></tr></thead><tbody><tr><td><code>http://192.168.1.8:11434/v1</code></td><td><code>http://localhost:11434/v1</code></td></tr><tr><td><code>http://192.168.1.8:1234/v1</code></td><td><code>http://192.168.1.8:1234/v1/chat/completions</code></td></tr><tr><td><code>http://192.168.1.8:5001/v1</code></td><td><code>https://192.168.1.8:11434/v1</code> (ohne Zertifikat kein erzwungenes https)</td></tr><tr><td><code>http://192.168.1.8:8080/v1</code></td><td></td></tr></tbody></table><h2 id="klartext-http" tabindex="-1">Klartext-HTTP <a class="header-anchor" href="#klartext-http" aria-label="Permalink to &quot;Klartext-HTTP&quot;">​</a></h2><p>MiniTavern <strong>Android</strong> erlaubt Klartext-HTTP (üblich im LAN). Wenn trotzdem blockiert:</p><ul><li>Base URL ist <code>http://</code>, nicht falsches Protokoll</li><li>System-/Hersteller-Netzschutz blockiert LAN nicht</li><li>iOS bei ATS: LAN-Adresse laut Doku; weiter fehlgeschlagen → OS-Version und Fehler melden</li></ul><h2 id="cors" tabindex="-1">CORS <a class="header-anchor" href="#cors" aria-label="Permalink to &quot;CORS&quot;">​</a></h2><p>CORS betrifft vor allem Browser-Seiten; <strong>native Apps</strong> zum API meist nicht. Browser-Frontend am PC ≠ MiniTavern — App-interner Test gilt.</p><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Fix</th></tr></thead><tbody><tr><td>Erstes Token sehr langsam</td><td>kleinere Quantisierung/Parameter; GPU prüfen</td></tr><tr><td>Hängt mitten in der Generierung</td><td>Timeout hoch; andere VRAM-Apps zu; PC-Logs auf OOM</td></tr></tbody></table><h2 id="verwandte-links" tabindex="-1">Verwandte Links <a class="header-anchor" href="#verwandte-links" aria-label="Permalink to &quot;Verwandte Links&quot;">​</a></h2><ul><li><a href="/ultra_guides/de/manual/errors">Handbuch · Fehlercodes</a> (API-Fehler bei Test / Chat)</li><li><a href="/ultra_guides/de/quickstart">30-Minuten-Quickstart</a></li><li><a href="/ultra_guides/de/local/tools">Tool-Übersicht</a> · <a href="/ultra_guides/de/local/models">Empfohlene Modelle</a></li><li><a href="/ultra_guides/de/ollama/lan">Ollama LAN</a></li><li><a href="/ultra_guides/de/lmstudio/server">LM Studio Local Server</a></li><li><a href="/ultra_guides/de/koboldcpp/server">KoboldCPP API</a></li><li><a href="/ultra_guides/de/llamacpp/server">llama.cpp server</a></li><li><a href="/ultra_guides/de/connect-app/minitavern">MiniTavern konfigurieren</a></li></ul>',17)])])}const m=t(d,[["render",i]]);export{b as __pageData,m as default};
